INSERT INTO `news_articles` (`slug`, `title`, `category_id`, `article_type`, `outlet`, `author`, `published_on`, `summary`, `content`, `content_plain`, `external_url`, `image_url`, `image_alt`, `is_published`, `is_featured`) VALUES ('himani-shah-inaugurates-embodied-enlightenment', 'Himani Shah inaugurates exhibition ''Embodied Enlightenment: A Decade Later''', (SELECT `id` FROM `news_categories` WHERE `slug` = 'news'), (SELECT `name` FROM `news_categories` WHERE `slug` = 'news'), 'Online Khabar', NULL, '2026-11-16', 'Online Khabar''s coverage of the 16 November 2026 inauguration of ''Embodied Enlightenment: A Decade Later'', the retrospective of Samundra Man Singh Shrestha at Kupondole. HRH Crown Princess Himani Rajya Laxmi Devi Shah lit the traditional butter lamp; Co-Founder Anjana Shakya felicitated the artist''s mother and wife in recognition of the family''s support, and HRH toured the exhibition with the artist and Director Prajwol Man Shakya. The programme included a Charya Nritya performance by Hem Bajracharya and his team. Entry is Rs 200; Bodhisattva International matches every ticket with its own Rs 200 contribution to the Prime Minister''s Disaster Relief Fund.', NULL, NULL, 'https://english.onlinekhabar.com/himani-shah-inaugurates-exhibition-embodied-enlightenment-a-decade-later-in-lalitpur.html', '/images/news/himani-shah-inaugurates-embodied-enlightenment.jpg', 'HRH Crown Princess Himani lighting the traditional butter lamp to inaugurate the exhibition, with Anjana Shakya and Prajwol Man Shakya — Photo: Bodhisattva Gallery', 1, 0) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `category_id` = VALUES(`category_id`), `article_type` = VALUES(`article_type`), `outlet` = VALUES(`outlet`), `author` = VALUES(`author`), `published_on` = VALUES(`published_on`), `summary` = VALUES(`summary`), `content` = VALUES(`content`), `content_plain` = VALUES(`content_plain`), `external_url` = VALUES(`external_url`), `image_url` = VALUES(`image_url`), `image_alt` = VALUES(`image_alt`), `is_published` = VALUES(`is_published`), `is_featured` = VALUES(`is_featured`);
