INSERT INTO `news_articles` (`slug`, `title`, `category_id`, `article_type`, `outlet`, `author`, `published_on`, `summary`, `content`, `content_plain`, `external_url`, `image_url`, `image_alt`, `is_published`, `is_featured`) VALUES ('himani-inaugurates-art-exhibition-kathmandu', 'Former Crown Princess Himani inaugurates art exhibition in Kathmandu', (SELECT `id` FROM `news_categories` WHERE `slug` = 'news'), (SELECT `name` FROM `news_categories` WHERE `slug` = 'news'), 'The Himalayan Times', 'THT Online', '2026-11-16', 'The Himalayan Times reports the inauguration of ''Embodied Enlightenment: A Decade Later'' at the Purna Museum of Newa Art and Bodhisattva Gallery, Kupondole, by former Crown Princess Himani Rajya Laxmi Devi Shah on 16 November 2026. The retrospective marks a decade of Samundra Man Singh Shrestha''s artistic journey, bringing together familiar artworks alongside previously unexhibited pieces; HRH lit the traditional butter lamp and presented tokens of appreciation to artists from the original 2016 exhibition. Open daily 12 PM – 7 PM until 27 December 2026; entry Rs 200, with proceeds to the Prime Minister''s Disaster Relief Fund.', NULL, NULL, 'https://thehimalayantimes.com/kathmandu/former-crown-princess-himani-inaugurates-art-exhibition-in-kathmandu', '/images/news/himani-inaugurates-art-exhibition-kathmandu.jpg', 'Co-Founder Anjana Shakya and HRH Crown Princess Himani with artist Samundra Man Singh Shrestha holding his Green Tara painting at the inauguration, Purna Museum of Newa Art', 1, 0) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `category_id` = VALUES(`category_id`), `article_type` = VALUES(`article_type`), `outlet` = VALUES(`outlet`), `author` = VALUES(`author`), `published_on` = VALUES(`published_on`), `summary` = VALUES(`summary`), `content` = VALUES(`content`), `content_plain` = VALUES(`content_plain`), `external_url` = VALUES(`external_url`), `image_url` = VALUES(`image_url`), `image_alt` = VALUES(`image_alt`), `is_published` = V