INSERT INTO `news_articles` (`slug`, `title`, `category_id`, `article_type`, `outlet`, `author`, `published_on`, `summary`, `content`, `content_plain`, `external_url`, `image_url`, `image_alt`, `is_published`, `is_featured`) VALUES ('art-exhibition-opens-at-bodhisattva', 'Art exhibition opens at Bodhisattva', (SELECT `id` FROM `news_categories` WHERE `slug` = 'news'), (SELECT `name` FROM `news_categories` WHERE `slug` = 'news'), 'The Rising Nepal', 'Staff Reporter', '2026-11-17', 'The Rising Nepal reports the opening of ''Embodied Enlightenment: A Decade Later'' at the Purna Museum of Newa Art and Bodhisattva Gallery, Lalitpur, inaugurated by former Crown Princess Himani Rajya Laxmi Devi Shah. The exhibition celebrates ten years of Samundra Man Singh Shrestha''s art, reuniting works from his landmark 2016 exhibition with previously unseen pieces; the ceremony featured a Charya Nritya performance by Hem Bajracharya and his team and a special performance by a young member of the founding family. Open to the public 16 November – 27 December 2026, noon to 7 PM daily; entry Rs 200, all proceeds to the Prime Minister''s Disaster Relief Fund.', NULL, NULL, 'https://risingnepaldaily.com/news/88699', '/images/news/art-exhibition-opens-at-bodhisattva.jpg', 'HRH Crown Princess Himani presenting a token of appreciation at the inauguration ceremony, with Co-Founder Anjana Shakya — Photo: Bodhisattva Gallery', 1, 0) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `category_id` = VALUES(`category_id`), `article_type` = VALUES(`article_type`), `outlet` = VALUES(`outlet`), `author` = VALUES(`author`), `published_on` = VALUES(`published_on`), `summary` = VALUES(`summary`), `content` = VALUES(`content`), `content_plain` = VALUES(`content_plain`), `external_url` = VALUES(`external_url`), `image_url` = VALUES(`image_url`), `image_alt` = VALUES(`image_alt`), `is_published` = VALUES(`is_published`), `is_featured` = VALUES(`is_featured`);
--> statement-breakpoint
UPDATE `exhibitions` SET `description` = 'A retrospective exhibition of Samundra Man Singh Shrestha by Bodhisattva International. For the first time in the history of Nepali art, an exhibition is re-celebrated a decade later: Embodied Enlightenment returns, bringing audiences back to the original 2016 retrospective while revealing how its artist has evolved over the past ten years. Works from the private collection of Anjana and the late Purna Man Shakya, originally presented in the landmark exhibition, are shown alongside eleven new and previously unseen works by the artist.

The exhibition was inaugurated on 16 November 2026 by HRH Crown Princess Himani Rajya Laxmi Devi Shah, who lit the traditional butter lamp and presented tokens of appreciation to artists who had contributed to the original 2016 exhibition. Co-Founder Anjana Shakya felicitated the artist''s mother and wife, honouring the family''s support throughout his career; the ceremony included a Charya Nritya performance by Hem Bajracharya and his team and a special performance by a young member of the founding family, after which HRH toured the exhibition with the artist and Director Prajwol Man Shakya.

Open daily 12 PM – 7 PM. Entry is Rs 200, and Bodhisattva International matches every ticket with its own Rs 200 contribution to the Prime Minister''s Disaster Relief Fund. On Sundays at 4 PM the artist leads a tour of the exhibition (limited seats — please sign up in advance). The exhibition catalogue, posters and merchandise are available at the gift shop, and parking is available on site.' WHERE `slug` = 'ten-years-of-celebrating-embodied-enlightenment';
--> statement-breakpoint
UPDATE `exhibitions` SET `description` = 'A first-of-its-kind solo exhibition dedicated to a traditional Newa statue maker, celebrating one of Nepal''s senior living master wax-model makers at the age of 83. Spanning the 1990s to 2026, it brought together early works and final cast statues in bronze, copper and silver, all from the collections of Anjana Shakya, the late Purna Man Shakya and Bodhisattva Gallery. Inaugurated by Deputy Mayor of Lalitpur Manjali Shakya Bajracharya, with a special edition catalogue documenting his contribution to traditional Newa statue making.

In keeping with the gallery''s commitment to the masters behind the work, every piece in the exhibition was bought and paid for directly from the artist before the show, and the gallery added five per cent of the sale prices to the artist. At the inauguration, the artist''s wife, Laxmi Shova Bajracharya, was felicitated alongside him.' WHERE `slug` = 'the-art-of-babu-kaji-bajracharya';
--> statement-breakpoint
UPDATE `exhibitions` SET `description` = CONCAT(`description`, ' Ten years on, the retrospective was revisited as ''10 Years of Celebrating Embodied Enlightenment'' at the Purna Museum of Newa Art & Bodhisattva Gallery, Kupondole (16 November – 27 December 2026), where artists from the original exhibition were honoured at the inauguration.') WHERE `slug` = 'embodied-enlightenment-2016' AND `description` LIKE '%cotton canvas.';
--> statement-breakpoint
UPDATE `page_sections` ps JOIN `pages` p ON (ps.`revision_id` = p.`published_revision_id` OR ps.`revision_id` = p.`draft_revision_id`) SET ps.`config` = '{"sectionLabel":"History","heading":"A History of Collecting","items":[{"yearLabel":"1986","text":"Purna Man Shakya begins collecting Newa art — the beginnings of Bodhisattva."},{"yearLabel":"2011","text":"Jewels of Newar Art at Siddhartha Art Gallery presents the collection to wide acclaim; the Jewels of Newar Art book is launched."},{"yearLabel":"2019","text":"Bodhisattva Gallery opens its permanent home in Pulchowk, Lalitpur; works from the collection travel to Nepal Art Now at the Weltmuseum Wien."},{"yearLabel":"2023","text":"Purna Museum of Newa Art opens with A Collector''s Collection; the Bodhisattva Foundation establishes the Purna Man Shakya Memorial Art Award."},{"yearLabel":"2026","text":"10 Years of Celebrating Embodied Enlightenment revisits Samundra Man Singh Shrestha''s landmark 2016 retrospective."}]}' WHERE p.`slug` = 'museum' AND ps.`sort_order` = 2;
--> statement-breakpoint
UPDATE `page_sections` ps JOIN `pages` p ON (ps.`revision_id` = p.`published_revision_id` OR ps.`revision_id` = p.`draft_revision_id`) SET ps.`config` = '{"sectionLabel":"History","headingLine1":"Founded in Conviction.","headingAccent":"Grown in Purpose.","paragraphs":["Bodhisattva International was founded in the 1980s by Anjana Shakya and her late husband Purna Man Shakya, guided by a philosophy they called ''The Art of Living''. What began as a commitment to commissioning and collecting the finest Newa art grew into a family mission: to build a renaissance of contemporary traditional Newa art, made to museum quality rather than for mass production. Purna Man Shakya''s collecting had begun in 1986, after he saw treasured Newa works quietly leaving the country.","Through Bodhisattva Gallery, the family has presented more than 24 major exhibitions in Nepal and abroad — from Jewels of Newar Art in Kathmandu to Nepal Art Now at the Weltmuseum Wien — and contributed works to international museum collections. In 2023 the Purna Museum of Newa Art opened in Kupondole, Lalitpur, housing the couple''s permanent collection: the world''s largest private collection dedicated to contemporary traditional Newa art.","Today Bodhisattva International unites four arms — the Purna Museum of Newa Art, Bodhisattva Gallery, the Bodhisattva Foundation, and the Bodhisattva Gift Shop — preserving sacred knowledge, nurturing artists, and building bridges across generations and geographies.",\"In December 2025, Director Prajwol Man Shakya was featured in WOW Magazine''s ''Collectors with Vision'', recognising the family''s place among Nepal''s new generation of collectors.\"],"image":{"url":"/images/pages/about-history.jpg","alt":"Painted Lakhey mask from the Nepal Art Now exhibition at Weltmuseum Wien"},"imageAspect":"16:9","quote":{"text":"Art is not only to be preserved, but lived; not only to be admired, but experienced; and not only to represent culture, but to sustain it.","attribution":"Bodhisattva International"}}' WHERE p.`slug` = 'about' AND ps.`sort_order` = 1;
--> statement-breakpoint
UPDATE `page_sections` ps JOIN `pages` p ON (ps.`revision_id` = p.`published_revision_id` OR ps.`revision_id` = p.`draft_revision_id`) SET ps.`config` = '{"sectionLabel":"Our Mission","headingLine1":"Art as an Act","headingAccent":"of Responsibility","paragraphs":["Beyond the realm of art, the Bodhisattva Foundation extends the founders'' legacy into society. It is dedicated to humanitarian work, education, and the nurturing of emerging artists. Its most significant initiative is the Purna Man Shakya Memorial Art Award, which honours the founders'' philosophy of artistic excellence for both senior and emerging artists.","Beyond his role as a cultural visionary, the late Purna Man Shakya was deeply committed to humanitarian values — supporting children''s education, funding medical treatment for those in need, and offering protection and support to individuals during Nepal''s periods of political conflict. Today those values live on through the Foundation.",\"In July 2026, marking the sixth anniversary of Purna Man Shakya''s passing, the Bodhisattva family donated NPR 400,005 towards the restoration of Hiranya Varna Mahavihar — the Golden Temple — in Patan.\"],"image":{"url":"/images/pages/foundation-mission.jpg","alt":"Third Purna Man Shakya Memorial Art Award 2025 poster"},"imageAspect":"4:3"}' WHERE p.`slug` = 'foundation' AND ps.`sort_order` = 2;
